CREATE VIEW [CE].[vwSalesOrderDetail]
AS 
SELECT
	sod.[SalesOrderDetailId],
	sod.[SalesOrderId],
	sod.[ricsv1_eventidName],
	sod.[OwnerId],
	sod.[OwnerIdName],
	sod.[SalesOrderStateCode],
	sod.[Statecode_Description],
	sod.[OwningBusinessUnit],
	sod.[SalesOrderIsPriceLocked],
	sod.[OwningUser],
	sod.[ProductId],
	sod.[productnumber],
	sod.[Order_ProductTypeCode],
	sod.[Order_ProductTypeCode_Description],
	sod.[RICS_ProductGroupId],
	sod.[TransactionCurrencyIdName],
	sod.[isocurrencycode],
	sod.[CreatedBy],
	sod.[CreatedByName],
	sod.[Created_On],
	sod.[ModifiedBy],
	sod.[ModifiedByName],
	sod.[Modified_On],
	sod.[IsProductOverridden],
	sod.[IsPriceOverridden],
	sod.[QuantityShipped],
	sod.[LineItemNumber],
	sod.[QuantityBackordered],
	sod.[QuantityCancelled],
	sod.[Quantity],
	sod.[PricePerUnit],
	sod.[BaseAmount],
	sod.[ExtendedAmount],
	sod.[Tax],
	sod.[ManualDiscountAmount],
	sod.[VolumeDiscountAmount],
	sod.[ExchangeRate],
	sod.[SequenceNumber],
	sod.[Rics_LengthofSubscription],
	sod.[Rics_Status],
	sod.[RICS_Status_Description],
	sod.[ricsv1_StartDate],
	sod.[ricsv1_EndDate],
	sod.[ricsv2_MarketingCode],
	sod.[ExtendedAmount_Base],
	sod.[BaseAmount_Base],
	sod.[Tax_Base],
	'CE' AS [Source]
FROM [synapse_ce].[vwSalesOrderDetail] sod
